<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;class RoomCategory extends Model{protected $fillable=['name','color','daily_price','weekly_price','monthly_price','facilities'];protected $casts=['daily_price'=>'decimal:2','weekly_price'=>'decimal:2','monthly_price'=>'decimal:2','facilities'=>'array'];public function rooms(){return $this->hasMany(Room::class);}public function photos(){return $this->hasMany(MediaFile::class)->where('kind','CATEGORY')->orderBy('position')->orderBy('id');}public function thumbnail(){return $this->hasOne(MediaFile::class)->where('kind','CATEGORY')->where('is_thumbnail',true)->orderBy('id');}public function waitingLists(){return $this->hasMany(WaitingListEntry::class,'room_category_id');}}
